using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows.Forms;

namespace AgitCon {
    static class BundleTests {
        sealed class BundleFixture:CollectionForm {
            protected override bool ShowWithoutActivation{get{return true;}}
            public BundleFixture(List<Entry> items,Action<int> remove,Action clear,Action<BundleMode> copy,bool doubleMode=false):base(items,remove,clear,copy,doubleMode){}
        }
        public static void RenderSaved(){Application.EnableVisualStyles();var entries=Catalog.Load().Entries.Where(e=>!String.IsNullOrEmpty(e.Path)&&File.Exists(e.Path)).Take(1).ToList();if(entries.Count<9&&Directory.Exists(DcShop.CacheRoot)){foreach(string path in Directory.EnumerateFiles(DcShop.CacheRoot,"*",SearchOption.AllDirectories).Where(Catalog.Supported)){if(entries.Count>=9)break;if(!entries.Any(e=>e.Path==path))entries.Add(new Entry{Path=path});}}using(var form=new BundleFixture(entries.Take(1).ToList(),i=>{},()=>{},m=>{})){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();for(int i=0;i<30;i++){Application.DoEvents();Thread.Sleep(20);}using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"collection-preview.png"));}}using(var form=new SemanticSettingsForm(false,v=>{})){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"semantic-preview.png"));}}}
        static IEnumerable<PictureBox> FindPictures(Control root){foreach(Control c in root.Controls){if(c is PictureBox)yield return (PictureBox)c;foreach(var p in FindPictures(c))yield return p;}}
        static IEnumerable<Button> FindButtons(Control root){foreach(Control c in root.Controls){if(c is Button)yield return (Button)c;foreach(var b in FindButtons(c))yield return b;}}
        static int checks;static void Check(bool value,string label){if(!value)throw new Exception(label);checks++;}
        static void Reject(Action action,string label){bool failed=false;try{action();}catch{failed=true;}Check(failed,label);}
        public static void Run(){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"bundle-test-data",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);ImageBundle.OutputRoot=Path.Combine(root,"outbox");
            try{checks=0;string source=Path.Combine(root,"source.png"),other=Path.Combine(root,"other.png");
                using(var image=new Bitmap(10,11)){image.SetResolution(288,288);for(int y=0;y<image.Height;y++)for(int x=0;x<image.Width;x++)image.SetPixel(x,y,Color.FromArgb(255,x*17,y*19,50));image.SetPixel(0,0,Color.Transparent);image.Save(source,ImageFormat.Png);}using(var image=new Bitmap(5,4))image.Save(other,ImageFormat.Png);
                var tiles=ImageBundle.Create(new[]{source},BundleMode.SplitNine,CancellationToken.None);Check(tiles.Count==9,"Nine split tiles");Check(Path.GetFileName(tiles[0]).EndsWith("_01.png")&&Path.GetFileName(tiles[8]).EndsWith("_09.png"),"Row-major filenames");var nextTiles=ImageBundle.Create(new[]{source},BundleMode.SplitNine,CancellationToken.None);Check(!tiles.Select(Path.GetFileName).Intersect(nextTiles.Select(Path.GetFileName)).Any(),"Separate split batches never share filenames");Check(nextTiles.SequenceEqual(nextTiles.OrderBy(Path.GetFileName,StringComparer.Ordinal)),"Repeated split keeps row-major lexical order");Check(ImageBundle.PrepareAttachments(tiles,false,CancellationToken.None).SequenceEqual(tiles),"Disabled resize retains exact picker batch");Reject(()=>PreviewPaste.AttachmentFileNames(new[]{tiles[0],nextTiles[1]},2),"Different picker folders remain rejected");var payload=ImageBundle.SplitPayload(tiles);Check(payload.ContainsFileDropList(),"FileDrop payload");Check(PreviewPaste.NineFileNames(tiles)==String.Join(" ",tiles.Select(p=>"\""+Path.GetFullPath(p)+"\"")),"All nine quoted absolute paths in picker order");Reject(()=>PreviewPaste.NineFileNames(Enumerable.Repeat(tiles[0],9).ToList()),"Duplicate picker files rejected");Check(payload.GetFileDropList().Cast<string>().SequenceEqual(tiles.Select(Path.GetFullPath)),"Nine clipboard file paths preserve row-major order");Reject(()=>ImageBundle.SplitPayload(tiles.Take(8).ToList()),"Incomplete clipboard batch rejected");
                using(var original=new Bitmap(source)){bool same=true;for(int row=0;row<3;row++)for(int col=0;col<3;col++)using(var tile=new Bitmap(tiles[row*3+col])){int left=col*original.Width/3,top=row*original.Height/3;Check(tile.Width==(col+1)*original.Width/3-left&&tile.Height==(row+1)*original.Height/3-top,"Odd dimension coverage");for(int y=0;y<tile.Height;y++)for(int x=0;x<tile.Width;x++)if(tile.GetPixel(x,y).ToArgb()!=original.GetPixel(left+x,top+y).ToArgb())same=false;}Check(same,"Lossless reconstruction including transparent pixel");}
                var batch=ImageBundle.Create(Enumerable.Repeat(source,9).ToArray(),BundleMode.Originals,CancellationToken.None);Check(batch.Distinct().Count()==9,"Duplicate stickers have distinct file paths");Check(batch.All(p=>File.ReadAllBytes(p).SequenceEqual(File.ReadAllBytes(source))),"Original bytes preserved");
                var merge=ImageBundle.Create(new[]{source,source,source},BundleMode.Merge,CancellationToken.None);using(var image=new Bitmap(merge.Single()))Check(image.Width==30&&image.Height==11,"Three equal images merged horizontally");
                using(var original=new Bitmap(source))using(var joined=new Bitmap(merge.Single())){bool equal=true;for(int i=0;i<3;i++)for(int y=0;y<original.Height;y++)for(int x=0;x<original.Width;x++){Color c=original.GetPixel(x,y),d=joined.GetPixel(i*original.Width+x,y);if(c.A!=d.A||(c.A==255&&c.ToArgb()!=d.ToArgb()))equal=false;}Check(equal,"High-DPI merge retains all source pixels");}
                Reject(()=>ImageBundle.Create(new[]{source,other},BundleMode.Merge,CancellationToken.None),"Mixed dimensions rejected");Reject(()=>ImageBundle.Create(new[]{source,source},BundleMode.SplitNine,CancellationToken.None),"Split needs exactly one");Reject(()=>ImageBundle.Create(Enumerable.Repeat(source,10).ToArray(),BundleMode.Originals,CancellationToken.None),"More than nine rejected");
                // Tiny, generated two-frame GIF; no user image is edited in tests.
                string gif=Path.Combine(root,"animated.gif");File.WriteAllBytes(gif,new byte[]{71,73,70,56,57,97,1,0,1,0,128,0,0,0,0,0,255,255,255,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,68,1,0,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,76,1,0,59});
                using(var image=Image.FromFile(gif))Check(ImageBundle.Animated(image),"Animated GIF detected");Reject(()=>ImageBundle.Create(new[]{gif},BundleMode.SplitNine,CancellationToken.None),"Animated split refused");Reject(()=>ImageBundle.Create(new[]{gif,gif},BundleMode.Merge,CancellationToken.None),"Animated merge refused");
                var gifCopy=ImageBundle.Create(new[]{gif},BundleMode.Originals,CancellationToken.None);Check(File.ReadAllBytes(gifCopy[0]).SequenceEqual(File.ReadAllBytes(gif)),"GIF bytes unchanged");var doubleFiles=ImageBundle.Create(new[]{gif,source},BundleMode.Double,CancellationToken.None);Check(doubleFiles.Count==2,"Two original files for double sticker");Check(File.ReadAllBytes(doubleFiles[0]).SequenceEqual(File.ReadAllBytes(gif))&&File.ReadAllBytes(doubleFiles[1]).SequenceEqual(File.ReadAllBytes(source)),"Double preserves GIF and PNG original bytes");Check(PreviewPaste.AttachmentFileNames(doubleFiles,2).Contains(Path.GetFileName(doubleFiles[1])),"Double file picker includes both originals");Reject(()=>ImageBundle.Create(new[]{source},BundleMode.Double,CancellationToken.None),"Double needs two sources");
                using(var token=new CancellationTokenSource()){token.Cancel();Reject(()=>ImageBundle.Create(new[]{source},BundleMode.Originals,token.Token),"Export cancellation");}
                var entries=batch.Select((p,i)=>new Entry{Path=p,DisplayName="콘 "+(i+1)}).ToList();Application.EnableVisualStyles();using(var form=new BundleFixture(entries.Take(1).ToList(),i=>{},()=>{},m=>{})){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();for(int i=0;i<80;i++){Application.DoEvents();Thread.Sleep(15);}Check(FindPictures(form).Count(p=>p.Image!=null)==9,"All nine preview tiles loaded");Check(FindPictures(form).First().Parent.Width>250&&Math.Abs(FindPictures(form).First().Parent.Width-FindPictures(form).First().Parent.Height)<=1,"Preview uses square stage area");Check(FindButtons(form).Single(b=>b.Text=="9개로 쪼개서 카톡에 첨부").Enabled,"Split action ready after preview");form.SetBusy(true);Check(MainForm.SplitWindowForeground(form,form.Handle),"Disabled copy button keeps owned split foreground");Check(!MainForm.SplitWindowForeground(form,IntPtr.Zero),"Another foreground is not split owner");form.SetBusy(false);using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"collection-preview.png"));}}
                using(var form=new BundleFixture(new List<Entry>{new Entry{Path=gif},new Entry{Path=source}},i=>{},()=>{},mode=>{},true)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();for(int i=0;i<80;i++){Application.DoEvents();Thread.Sleep(15);}var pictures=FindPictures(form).ToList();Check(pictures.Count==2&&pictures.All(p=>p.Image!=null),"Double previews two originals");Check(ImageBundle.Animated(pictures[0].Image),"Double GIF preview retains animation");Check(FindButtons(form).Single(b=>b.Text=="더블콘을 카톡에 첨부").Enabled,"Double attachment ready");using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"double-preview.png"));}}
                File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"bundle-test.txt"),"PASS: "+checks+" bundle checks and 9-slice preview and ordered in-memory FileDrop payload. No system clipboard or KakaoTalk interaction.\r\n");
            }catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"bundle-test.txt"),"FAIL: "+ex);Environment.ExitCode=1;}
        }
    }
}
